def _tools_without_listen(tool_calls: List[LLMToolCall]) -> List[LLMToolCall]:
    """Return tool calls with ``listen`` removed so mixed batches keep other intent.

    Used by response routing and the post-search latch so those two sites
    cannot drift.
    """
    return [tool_call for tool_call in tool_calls if tool_call.tool_name != TOOL_LISTEN]


def _stack_signature(tracker_handle: TrackerHandle) -> Tuple[Tuple[str, Any], ...]:
    """Return each frame's id and type, to tell whether a tool changed the stack."""
    return tuple(
        (frame.frame_id, getattr(frame, "frame_type", None))
        for frame in tracker_handle.stack.frames
    )


def _activated_frame_ids(tracker_handle: TrackerHandle) -> FrozenSet[str]:
    """Return the frames of the skill an ``activate`` just made active.

    That is the live top span plus, when the activated skill has an unmet
    precondition, its ``PENDING`` consumer under the resolver: the consumer's
    first ask still answers the activating message once the resolver is done.
    """
    frames = tracker_handle.stack.frames
    top_ids = top_live_span_frame_ids(frames)
    lowest = next(
        (index for index, frame in enumerate(frames) if frame.frame_id in top_ids),
        None,
    )
    if lowest is None:
        return top_ids
    return top_ids | pending_consumer_frame_ids_below(frames, lowest)


def _any_activated_skill_is_live(
    tracker_handle: TrackerHandle, frame_id_groups: List[FrozenSet[str]]
) -> bool:
    """Return whether any skill activated this turn is still live.

    Each group holds the frames of the skill one ``activate`` made active.
    Groups are checked separately so a parked skill's ``REGULAR`` frames
    cannot make it look live. A parked frame above a skill (the skill itself,
    or a callee of it, answered a knowledge question) means the engine is
    about to offer a resume prompt rather than continue that skill.
    """
    frames = tracker_handle.stack.frames
    return any(span_is_live(frames, frame_ids) for frame_ids in frame_id_groups)


class _HookedLlmCompletion(NamedTuple):
    """One completion after model request and response hooks."""

    response: LLMResponse
    text: Optional[str]
    tool_calls: List[LLMToolCall]
    discarded: bool
    streamed: bool


def _hangup_last(tool_calls: List[LLMToolCall]) -> List[LLMToolCall]:
    """Return tool calls with ``hangup`` moved behind every other call."""
    return [
        *(call for call in tool_calls if call.tool_name != TOOL_HANGUP),
        *(call for call in tool_calls if call.tool_name == TOOL_HANGUP),
    ]


class _MainLlmCallFailed(Exception):
    """Provider failure from an LLM completion.

    Distinct from span-serialization errors so callers can map only provider
    failures onto a fallback while letting other exceptions (for example
    Langfuse output recording) propagate unchanged. Quiet calls
    (rephrase, confirm-rephrase, post-activate ``set_fields``) use the same
    wrapper as the main loop.
    """

    def __init__(self, cause: Exception) -> None:
        super().__init__(str(cause))
        self.cause = cause


def _is_empty_llm_response(response: LLMResponse) -> bool:
    """Return True when the completion has neither text nor tool calls."""
    return not response.response_text() and not (response.tool_calls or [])


def _advance_steps_output(agent_response: Optional[AgentResponse]) -> Dict[str, Any]:
    """Summarize an ``advance_steps`` result for the Langfuse span output.

    Any response text goes in the span *output* (never metadata, which is not
    redacted); ``mode``/``rephrase`` are structural flags describing the phase.
    """
    if agent_response is None:
        return {"produced_response": False}
    return {
        "produced_response": True,
        "mode": agent_response.mode.value,
        "rephrase": agent_response.rephrase is not None,
        "rephrase_kind": rephrase_kind_label(agent_response.rephrase),
        "text": agent_response.text,
    }


def _llm_response_output(response: LLMResponse) -> Dict[str, Any]:
    """Summarize an LLM response (text + tool calls) for the span output."""
    tool_calls = response.tool_calls or []
    return {
        "text": response.response_text(),
        "tool_calls": [
            {"name": tc.tool_name, "args": tc.tool_args} for tc in tool_calls
        ],
    }


class Orchestrator:
    """Coordinates one turn over prompt, phase advancement, and LLM.

    Implements ``OrchestratorProtocol``.
    """

    def __init__(
        self,
        skill_executor: SkillExecutor,
        prompt_constructor: PromptConstructorProtocol,
        static_data: ModelBootstrap,
    ) -> None:
        self._skill_executor = skill_executor
        self._prompt_constructor = prompt_constructor
        self._static_data = static_data
        self._skill_executor.set_completion_judge(CompletionJudge(static_data))

    # ------------------------------------------------------------------
    # Public entry point
    # ------------------------------------------------------------------

    @observe(
        name="run_turn",
        capture_input=False,
        capture_output=False,
    )
    async def run_turn(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
    ) -> TurnResult:
        """Execute one full user-message turn.

        A fresh ``PromptContext`` is assembled on every iteration from the
        live ``tracker_handle`` so the LLM always sees the current stack,
        slot values, and conversation history.  All prompt text (including
        the rephrase instruction) is owned by ``PromptConstructor``.

        Args:
            tracker_handle: Live state wrapper for the current tracker.
            turn: The initial user input; queued voice input may extend this turn.

        TODO(ENG-2820): Before any stack manipulation, run stale-frame cleanup
        to gracefully handle flows or steps that changed since the last turn
        on this tracker (model reload between turns).  Check the v1
        equivalent cleanup logic and reuse the same approach here.
        """
        # Resolve the ambient turn context once so the ``finally`` cannot raise
        # (and mask an in-flight exception) if the context were unavailable.
        turn_context = current_turn_context()
        try:
            reconsider = False
            while True:
                result = await self._iterate_turn(
                    tracker_handle, turn, reconsider=reconsider
                )
                if result is not None and (
                    turn_context.is_cancelled
                    or not await turn_context.take_pending_input()
                ):
                    return result
                # New user input was taken in: restart with it so per-input
                # setup (skill retrieval, executor state) reflects the new text.
                turn = turn_context.turn
                reconsider = True
        finally:
            update_current_span_metadata(span_output=turn_context.agent_messages)

    async def _iterate_turn(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        *,
        reconsider: bool = False,
    ) -> Optional[TurnResult]:
        """Run the deterministic-phase + LLM iteration loop for one turn.

        Extracted from :meth:`run_turn` so that span can record the final agent
        output around the loop; user text lives on the parent processor trace.

        New user input is taken in only where nothing is queued or half-handled:
        at the start of an iteration, before the prompt is built, and when an LLM
        response arrives (which is then dropped). A response the user spoke over
        ends the turn, so its tool calls never run. Tool batches and
        deterministic steps already under way finish first.

        Args:
            tracker_handle: Live state wrapper for the current tracker.
            turn: The user input this run answers.
            reconsider: Skip the first deterministic phase so the LLM answers
                newly taken-in input before further steps run.

        Returns:
            The turn result, or ``None`` when new user input was taken in and
            :meth:`run_turn` must restart with it.
        """
        llm_client = LLMClient.from_bootstrap(self._static_data)

        # The ack reminder belongs on the FIRST real LLM call of the turn, which
        # is not necessarily loop iteration 0: deterministic CONTINUE responses
        # from advance_steps loop again (bumping the index) without an LLM call.
        is_first_llm_iteration = True
        # Whether the model has called search_knowledge this turn. Once it answers
        # (text only) with a skill still active, we park that skill and offer to
        # resume it — the same digression re-anchoring an activate gets.
        knowledge_searched = False
        # After a successful same-turn activate, hold the first WAIT that
        # would wait for the user or pop this flow, then run one silent
        # ``set_fields``. Reset each turn; never persisted.
        # ``post_activate_fill_done`` is latched when that intercept starts so
        # a later activate cannot re-arm it.
        # ``post_activate_frame_groups`` holds, per activate this turn, the
        # frames of the skill it made active (newly pushed or resumed in
        # place). The fill is only for skills the user's message activated:
        # once none of them is live (they completed, or they or a callee
        # answered a knowledge question and were parked under
        # ``default_continue_interrupted``), the latch is dropped so another
        # skill's ask is delivered instead of silently pre-filled.
        post_activate_fill_pending = False
        post_activate_fill_done = False
        post_activate_frame_groups: List[FrozenSet[str]] = []
        # Turn-local RetryModel feedback from modify_model_response or
        # modify_tool_call. Injected as an engine-only system note on the next
        # request; never persisted.
        retry_feedback: Optional[str] = None

        self._skill_executor.begin_user_turn(tracker_handle)
        if (
            turn.trigger is IncomingTurnTrigger.DTMF
            and turn.dtmf_field_name is not None
            and turn.text
        ):
            write_result = await self._skill_executor.write_dtmf_collect_value(
                tracker_handle,
                turn.dtmf_field_name,
                turn.text,
            )
            if not write_result.ok:
                # The tool's own message can echo the rejected digits.
                reason = (
                    "memory_validation_rejected"
                    if write_result.memory_validation_failed
                    else write_result.error
                )
                structlogger.warning(
                    "mantle.orchestrator.dtmf_collect_write_failed",
                    field_name=turn.dtmf_field_name,
                    memory_validation_failed=write_result.memory_validation_failed,
                    reason=reason,
                )
        self._reconcile_silence_timeout_skill(tracker_handle, turn)
        try:
            retrieved_skill_ids = await skill_retrieval.retrieve_skill_ids_for_turn(
                self._static_data,
                tracker_handle.tracker,
                turn,
            )
        except skill_retrieval.SkillRetrievalSearchError as exc:
            return await self._skill_retrieval_error_result(exc, iteration=0)

        structlogger.info(
            "mantle.turn.started",
            active_flow=tracker_handle.active_flow_id,
            stack_depth=tracker_handle.stack_depth,
        )

        for iteration in range(_MAX_ITERATIONS):
            with langfuse_span(
                name="iteration",
                metadata={"iteration": iteration},
            ):
                structlogger.debug(
                    "mantle.orchestrator.iteration",
                    iteration=iteration,
                    stack_depth=tracker_handle.stack_depth,
                    highlight=True,
                )

                if current_turn_context().is_cancelled:
                    return self._cancelled_result(iteration)

                if await current_turn_context().take_pending_input():
                    return None

                # Unusable ``set:`` taps: utter the packaged notice and end before
                # advance_steps so a parked collect does not re-ask or BREAK into
                # the LLM.
                if turn.skip_set_memory_button_tap:
                    return await self._emit_set_memory_button_skip_notice(
                        tracker_handle,
                        turn,
                        llm_client,
                        iteration,
                    )

                if post_activate_fill_pending and not _any_activated_skill_is_live(
                    tracker_handle, post_activate_frame_groups
                ):
                    post_activate_fill_pending = False

                # ── Step 1: Deterministic phase advancement ────────────────────
                # Run all deterministic steps (utter, noop, set_slots, end, …)
                # before involving the LLM.  Returns an AgentResponse when the
                # phase produced output that needs to be handled, or None when
                # the stack is clean and the LLM should decide what to do next.
                with langfuse_span(
                    name="advance_steps",
                    metadata={"iteration": iteration},
                ) as span:
                    try:
                        agent_response = None
                        if not reconsider:
                            agent_response = (
                                await current_turn_context().run_cancellable(
                                    self._skill_executor.advance_steps(
                                        tracker_handle,
                                        defer_listen=post_activate_fill_pending,
                                    )
                                )
                            )
                        reconsider = False
                    except OperationCancelled:
                        return self._cancelled_result(iteration)
                    span.update(output=_advance_steps_output(agent_response))
                # Ordered-block execute_tool / memory writes may queue on_success,
                # on_failure, or when: utters — drain before WAIT/CONTINUE handling
                # so they are not stranded when the turn ends without LLM tools.
                queued_result = await self._emit_queued_verbatim_responses(
                    tracker_handle,
                    turn,
                    llm_client,
                    iteration,
                )
                if queued_result is not None:
                    self._drop_unsent_confirmation_handshake(
                        tracker_handle, skipped_ask=agent_response
                    )
                    return queued_result
                if agent_response is not None:
                    # The activating message may already answer the step this
                    # WAIT is about to ask for: write settable fields first,
                    # then let the next advance_steps re-decide what to say.
                    # A held listen is not advanced or recorded yet, so the
                    # next lap runs it and the turn still ends there. Hangup
                    # commits immediately: the call is ending, so the fill
                    # would have nothing left to use the value.
                    # A confirmation ask was rendered before the fill. That
                    # unsent handshake is dropped so the next lap pauses
                    # again and renders the question from the written memory.
                    if (
                        post_activate_fill_pending
                        and _any_activated_skill_is_live(
                            tracker_handle, post_activate_frame_groups
                        )
                        and self._should_hold_wait_for_post_activate_fill(
                            agent_response, tracker_handle
                        )
                    ):
                        post_activate_fill_pending = False
                        post_activate_fill_done = True
                        silent_set_fields_result = (
                            await self._fill_then_resume_held_wait(
                                agent_response,
                                tracker_handle,
                                turn,
                                llm_client,
                                iteration,
                            )
                        )
                        if silent_set_fields_result is not None:
                            return silent_set_fields_result
                        continue
                    result = await self._process_agent_response(
                        agent_response,
                        tracker_handle,
                        turn,
                        llm_client,
                        iteration,
                    )
                    # Drop pending when this ask never reached the user: muted
                    # after a barge-in, or an outgoing-text rejection that replaced
                    # it with a fallback. A delivered ask stays — including one the
                    # user heard before barge-in — so the next turn can resolve.
                    if result is not None and not self._confirmation_ask_was_delivered(
                        tracker_handle, agent_response
                    ):
                        self._drop_unsent_confirmation_handshake(
                            tracker_handle, skipped_ask=agent_response
                        )
                    if result is not None:
                        return result
                    continue  # CONTINUE — loop again from the updated stack state

                if self._session_start_finished_without_routing(tracker_handle, turn):
                    return self._completed_or_cancelled(
                        TurnResult(iteration_count=iteration),
                        source=_SOURCE_SESSION_START_FINISHED,
                    )

                # ── Step 2: Build prompt and tools for the normal LLM call ────
                # A fresh PromptContext is created each iteration so the LLM
                # always sees the latest stack, memory values, and conversation
                # history rather than a snapshot from the start of the turn.
                if await current_turn_context().take_pending_input():
                    return None
                messages, tools, gated_tool_names = self._build_llm_call(
                    tracker_handle,
                    turn,
                    knowledge_searched=knowledge_searched,
                    is_first_llm_iteration=is_first_llm_iteration,
                    retrieved_skill_ids=retrieved_skill_ids,
                )

                # On the first LLM call of the turn, reinforce the acknowledgement
                # right after the user message (skipped during a collect step,
                # where the ack rule competes with collect prompting).
                if (
                    is_first_llm_iteration
                    and resolve_ack_enabled(
                        self._static_data.agent.fillers, is_voice=turn.is_voice
                    )
                    and self._skill_executor.active_collect_step(tracker_handle) is None
                ):
                    messages = inject_ack_reminder(messages, self._static_data.agent)
                is_first_llm_iteration = False
                # Re-apply the token budget so the replayed tail cannot push the
                # prompt over the limit (the trim protects the tail and drops
                # history).
                messages = trim_history_to_budget(
                    messages,
                    max_tokens=resolve_max_prompt_tokens(self._static_data.llm),
                    model_name=resolve_llm_model_name(self._static_data.llm),
                )

                # ── Step 2b: model_request hooks ───────────────────────────────
                # Observers fire-and-forget; the modify lane may rewrite messages
                # and allowlisted per-call settings. Runs once per loop iteration
                # (empty-completion retries reuse the same request).
                try:
                    messages, model_settings = await apply_model_request_hooks(
                        self._static_data.hooks,
                        messages,
                        tools or None,
                        iteration=iteration,
                    )
                except HookExecutionError as exc:
                    return await self._hook_error_result(
                        exc,
                        iteration,
                        response_name=UTTER_MODEL_REQUEST_HOOK_ERROR,
                    )

                # Engine-owned RetryModel feedback: append after request hooks so
                # builders cannot strip the steering note.
                if retry_feedback is not None:
                    messages = [
                        *messages,
                        llm_message(ROLE_SYSTEM, retry_feedback),
                    ]
                    retry_feedback = None

                # ── Step 3: LLM call ───────────────────────────────────────────
                # Buffer the full completion when a response or tool-call
                # modifier is registered: streaming would reach the user
                # before hooks can rewrite text or discard via RetryModel
                # (tool-call preflight also drops accompanying text).
                hooks = self._static_data.hooks
                allow_streaming = (
                    hooks.modifier(POINT_MODEL_RESPONSE) is None
                    and hooks.modifier(POINT_TOOL_CALL) is None
                )
                if current_turn_context().is_cancelled:
                    return self._cancelled_result(iteration)
                try:
                    response = await self._call_main_llm_with_empty_retry(
                        llm_client,
                        messages,
                        tools=tools or None,
                        gated_tool_names=gated_tool_names or None,
                        model_settings=model_settings or None,
                        iteration=iteration,
                        allow_streaming=allow_streaming,
                    )
                except OperationCancelled:
                    return self._cancelled_result(iteration)
                except _MainLlmCallFailed as failed:
                    return await self._llm_error_result(failed.cause, iteration)
                # A user who spoke during the call is not answered by this
                # response: answer their new input, or end the turn so their
                # words start the next one. Checking the floor before taking
                # input catches a barge-in whose input is then rejected.
                ctx = current_turn_context()
                user_spoke = ctx.is_interrupted
                if await ctx.take_pending_input():
                    return None
                if user_spoke or ctx.is_interrupted:
                    return self._cancelled_result(iteration)

                llm_text = response.response_text()
                tool_calls = list(response.tool_calls or [])

                # ── Step 3b: model_response hooks ──────────────────────────────
                # Before any user-visible emit or tool dispatch. Fail-open on
                # unexpected crashes; RetryModel discards this response and
                # steers the next iteration under the existing iteration cap.
                hooked = await apply_model_response_hooks(
                    self._static_data.hooks,
                    text=llm_text,
                    tool_calls=tool_calls,
                    latency_ms=response.latency_ms,
                )
                if hooked.retry is not None:
                    retry_feedback = hooked.retry.feedback
                    continue
                llm_text = hooked.text
                tool_calls = hooked.tool_calls

                # ── Step 3c: tool-call preflight ───────────────────────────────
                # Rewrite / RetryModel the batch before listen-only routing and
                # the knowledge_searched latch so both see post-hook tool names.
                if tool_calls:
                    try:
                        preflight = await preflight_tool_calls(
                            self._static_data.hooks,
                            tool_calls,
                        )
                    except HookExecutionError as exc:
                        return await self._hook_error_result(
                            exc,
                            iteration,
                            response_name=UTTER_TOOL_CALL_HOOK_ERROR,
                        )
                    if preflight.retry is not None:
                        # Discarded before any dispatch — do not set the latch.
                        retry_feedback = preflight.retry.feedback
                        continue
                    tool_calls = preflight.tool_calls

                # ── Step 4: Handle LLM response ────────────────────────────────
                active_flow_before = tracker_handle.active_flow_id
                current_turn_context().take_activated_frame_groups()
                turn_result = await self._handle_llm_response(
                    llm_text=llm_text,
                    tool_calls=tool_calls,
                    tracker_handle=tracker_handle,
                    turn=turn,
                    llm_client=llm_client,
                    iteration=iteration,
                    knowledge_searched=knowledge_searched,
                    llm_response=response,
                    listen_available=self._listen_available(
                        tracker_handle,
                        knowledge_searched,
                        is_voice=turn.is_voice,
                    ),
                    streamed=allow_streaming,
                )
                if turn_result is not None:
                    return turn_result
                activated_frame_groups = (
                    current_turn_context().take_activated_frame_groups()
                )
                if (
                    not post_activate_fill_done
                    and any(tc.tool_name == TOOL_ACTIVATE for tc in tool_calls)
                    and tracker_handle.active_flow_id != active_flow_before
                ):
                    post_activate_fill_pending = True
                    post_activate_frame_groups.extend(activated_frame_groups)
                # Latch from the post-preflight batch only when search is
                # enabled. A turned-off call returns an error and never
                # queries; the name alone must not trim the next iteration.
                if builtin_tool_enabled(
                    self._static_data.agent.orchestrator.tool_constraints,
                    TOOL_SEARCH_KNOWLEDGE,
                ):
                    knowledge_searched = knowledge_searched or any(
                        tc.tool_name == TOOL_SEARCH_KNOWLEDGE for tc in tool_calls
                    )
                # Continue to next iteration. The two branches below manage the
                # `knowledge_searched` latch, which exists ONLY for the two-stage
                # search_knowledge answering loop (first stage runs the search;
                # while the latch is set the next iteration answers from the
                # retrieved documents with a trimmed tool set). Both branches
                # clear the latch to leave that loop; they have no effect on turns
                # where search_knowledge was never called.
                #
                # A text-only answer is the grounded reply to the search: clear
                # the latch so we park the skill and offer resume at most once per
                # turn — otherwise each resumed answer would re-interrupt the
                # skill and the turn would spin to max iterations.
                # Ignore listen the same way _handle_llm_response does: mixed
                # text + listen is a grounded answer, not a lingering tool batch.
                if llm_text and not _tools_without_listen(tool_calls):
                    knowledge_searched = False
                # A genuine flow activation (the active skill actually changed —
                # not a no-op re-activate of the current flow or a failed one)
                # also leaves the knowledge-answer loop: the newly activated skill
                # must get its full tool set and untrimmed prompt next iteration.
                elif tracker_handle.active_flow_id != active_flow_before:
                    knowledge_searched = False

        return await self._max_iterations_result(tracker_handle, turn, llm_client)

    # ------------------------------------------------------------------
    # Private helpers
    # ------------------------------------------------------------------

    def _listen_available(
        self,
        tracker_handle: TrackerHandle,
        knowledge_searched: bool,
        *,
        is_voice: bool,
    ) -> bool:
        """Whether this LLM call may wait silently via ``listen``.

        False while a pending confirmation or post-search answer owns the call,
        and on a collect step unless the channel is voice and the question was
        already asked — the same gates that hide the schema.
        """
        return (
            not knowledge_searched
            and tracker_handle.pending_tool_confirmation_for_active_frame() is None
            and self._collect_allows_listen(tracker_handle, is_voice=is_voice)
        )

    def _collect_allows_listen(
        self, tracker_handle: TrackerHandle, *, is_voice: bool
    ) -> bool:
        """Whether the active collect step, if any, permits a silent wait.

        Allowed only on a voice channel, and only when both hold:

        * the step's question was asked in an earlier turn, and
        * the agent has said nothing yet this turn, so the question is still
          the last thing the user heard.

        On text the user already sent a finished message, so a silent wait
        would look like a hang. When no collect step is active, the channel
        does not matter.

        The second check matters when another skill or handler takes over, sends
        a message, and hands back to the same collect step within one turn. For
        example, the user asks for something unsupported, the unsupported-request
        handler replies "Sorry, I can't help with that", and the engine resumes
        the paused skill on the same collect step. The agent must ask the
        question again rather than wait silently.
        """
        if self._skill_executor.active_collect_step(tracker_handle) is None:
            return True
        if not is_voice:
            return False
        return (
            self._skill_executor.collect_question_already_asked(tracker_handle)
            and not current_turn_context().agent_messages
        )

    def _reconcile_silence_timeout_skill(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
    ) -> None:
        """Apply the configured consecutive-silence retry policy."""
        if turn.trigger is IncomingTurnTrigger.USER_MESSAGE:
            silence_count = tracker_handle.tracker.get_slot(
                f"system.{SILENCE_TIMEOUT_COUNT_ENTRY}"
            )
            if silence_count not in (None, 0):
                tracker_handle.memory.set_system(SILENCE_TIMEOUT_COUNT_ENTRY, 0)
            if self._is_silence_timeout_active(tracker_handle):
                self._skill_executor.complete_delivered_step(tracker_handle)
                structlogger.debug(
                    "mantle.orchestrator.silence_timeout_resolved_by_user_turn",
                    sender_id=turn.sender_id,
                )
            return

        if turn.trigger is not IncomingTurnTrigger.SILENCE_TIMEOUT:
            return

        # The hangup skill is already ending the call. Further silence must not
        # re-activate and re-speak the farewell.
        if self._is_silence_hangup_active(tracker_handle):
            structlogger.debug(
                "mantle.orchestrator.silence_timeout_ignored_during_hangup",
                sender_id=turn.sender_id,
            )
            return

        if self._is_silence_timeout_active(tracker_handle):
            if not self._skill_executor.discard_active_lifecycle_default(
                tracker_handle
            ):
                structlogger.warning(
                    "mantle.orchestrator.silence_timeout_skill_discard_failed",
                    sender_id=turn.sender_id,
                )
                # Still count and try to escalate so a stuck check-in cannot
                # block hangup forever.

        # Unset until the first timeout of the conversation.
        current_count = tracker_handle.memory.get_system(SILENCE_TIMEOUT_COUNT_ENTRY)
        timeout_count = current_count + 1 if isinstance(current_count, int) else 1

        if timeout_count <= DEFAULT_SILENCE_TIMEOUT_RETRIES:
            skill_id = DEFAULT_SILENCE_TIMEOUT
        else:
            skill_id = DEFAULT_SILENCE_TIMEOUT_HANGUP
        skill = self._static_data.skill_catalog.skill_by_id(skill_id)
        target_id = entry_target_id_for_skill(skill) if skill is not None else None

        if (
            target_id is None
            or self._static_data.skill_catalog.resolve_activation_target(target_id)
            is None
        ):
            structlogger.warning(
                "mantle.orchestrator.silence_timeout_skill_unavailable",
                sender_id=turn.sender_id,
                target_id=target_id,
            )
            return

        tracker_handle.memory.set_system(SILENCE_TIMEOUT_COUNT_ENTRY, timeout_count)
        self._skill_executor.activate(
            target_id,
            tracker_handle,
            skill_id=skill_id,
        )

    def _silence_skill_id(self, tracker_handle: TrackerHandle) -> str | None:
        """Return the active silence skill id, check-in or hangup."""
        active_frame = tracker_handle.active_frame
        if active_frame is not None:
            skill_id = getattr(active_frame, "skill_id", None)
            if skill_id in (DEFAULT_SILENCE_TIMEOUT, DEFAULT_SILENCE_TIMEOUT_HANGUP):
                return skill_id
        active_flow_id = tracker_handle.active_flow_id or ""
        skill = self._static_data.skill_catalog.owning_skill_for_target_id(
            active_flow_id
        )
        if skill is None:
            return None
        if skill.id in (DEFAULT_SILENCE_TIMEOUT, DEFAULT_SILENCE_TIMEOUT_HANGUP):
            return skill.id
        return None

    def _is_silence_hangup_active(self, tracker_handle: TrackerHandle) -> bool:
        """Return whether the active frame is the silence hangup skill."""
        return self._silence_skill_id(tracker_handle) == DEFAULT_SILENCE_TIMEOUT_HANGUP

    def _is_silence_timeout_active(self, tracker_handle: TrackerHandle) -> bool:
        """Return whether the active frame is a silence check-in or hangup."""
        return self._silence_skill_id(tracker_handle) is not None

    def _session_start_finished_without_routing(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
    ) -> bool:
        """Return whether a suppressed session-start turn should stop.

        The opener stays out of this turn so the session-start skill does not
        answer it. Once that skill is no longer active, another model call
        would route against a system-only prompt. The following user-message
        turn includes the opener.
        """
        if turn.trigger is not IncomingTurnTrigger.SESSION_START:
            return False
        if not turn.suppress_llm_user_message:
            return False
        active_skill_id = lifecycle_skill_id_for_frame(
            self._static_data.skill_catalog,
            tracker_handle.active_frame,
        )
        return active_skill_id != DEFAULT_SESSION_START

    def _build_llm_call(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        knowledge_searched: bool = False,
        is_first_llm_iteration: bool = True,
        retrieved_skill_ids: Optional[tuple[str, ...]] = None,
    ) -> Tuple[List[LlmMessage], List[AgentToolSchema], List[str]]:
        """Build the prompt messages, tool schemas and gated-off tool names.

        A fresh ``PromptContext`` is constructed from the live tracker so the
        system prompt always reflects the current stack and memory state.  Tool
        schemas are derived from the active flow and any builder-defined tools.

        Rephrase calls are handled separately by ``_run_rephrase_call`` and do
        not go through this method. Silent ``set_fields`` fill uses
        ``_run_silent_set_fields_after_activate``.
        """
        active_target_id = tracker_handle.active_flow_id
        # Build prompt and gating/routing inputs from one schema-scoped view
        # (public/private/project) so the skill state shown in
        # the prompt, the routing catalogue, and the offered tools all match
        # what the SkillExecutor will actually permit at dispatch time. Using
        # raw tracker slots here would let those paths disagree on the same
        # ``session.*`` expression, surfacing state/tools/flows that then
        # block or fail.
        # Entries (field + value) feed the ``### Memory:`` listing; values are
        # derived from the same call so gating and the listing cannot drift.
        memory_entries = self._skill_executor.current_memory_entries(tracker_handle)
        memory_values = {name: entry.value for name, entry in memory_entries.items()}
        # Discovered once and shared: the active-skill correction reminder must
        # appear only when the same turn actually offers the ``correct`` tool, so
        # both derive from a single correctable-fields computation.
        correctable_memory_items = self._skill_executor.find_correctable_fields(
            tracker_handle
        )

        settable_fields, settable_descriptions = (
            self._skill_executor.settable_fields_for_turn(tracker_handle)
        )
        pending_tool_confirmation = (
            tracker_handle.pending_tool_confirmation_for_active_frame()
        )
        listen_available = self._listen_available(
            tracker_handle, knowledge_searched, is_voice=turn.is_voice
        )
        allowed_target_ids = skill_retrieval.startable_targets_for_retrieved_skills(
            self._static_data.skill_catalog,
            memory_values,
            active_target_id=tracker_handle.active_flow_id,
            retrieved_skill_ids=retrieved_skill_ids,
            tracker=tracker_handle.tracker,
        )
        tools = build_llm_tools_for_turn(
            bootstrap=self._static_data,
            memory_values=memory_values,
            mcp_runtime=self._skill_executor.mcp_runtime,
            active_target_id=tracker_handle.active_flow_id,
            settable_fields=settable_fields or None,
            settable_descriptions=settable_descriptions or None,
            correctable_memory_items=correctable_memory_items,
            knowledge_available=knowledge_search_offered(
                self._static_data.agent.orchestrator.tool_constraints,
                self._static_data.references_index is not None,
            ),
            knowledge_searched=knowledge_searched,
            pending_tool_confirmation=pending_tool_confirmation,
            listen_available=listen_available,
            allowed_target_ids=allowed_target_ids,
            paused_block_ids=paused_ordered_block_target_ids(
                tracker_handle.tracker, self._static_data.skill_catalog
            ),
        )
        # Reached only by a session-start override that is still active (the
        # bundled skill ends the turn before any model call). The opener is
        # omitted on this turn, so activate would route against a system-only
        # prompt. The following user-message turn offers it.
        if (
            turn.trigger is IncomingTurnTrigger.SESSION_START
            and turn.suppress_llm_user_message
        ):
            tools = [tool for tool in tools if tool.name != TOOL_ACTIVATE]

        context = PromptContext(
            tracker=tracker_handle.tracker,
            bootstrap=self._static_data,
            turn=turn,
            active_target=(
                self._static_data.skill_catalog.resolve_activation_target(
                    active_target_id
                )
                if active_target_id
                else None
            ),
            active_skill_id=tracker_handle.active_skill_id,
            memory_values=memory_values,
            memory_entries=memory_entries,
            memory_cleared_by_correction=tracker_handle.correction_in_progress,
            correct_tool_available=bool(correctable_memory_items),
            pending_tool_confirmation=pending_tool_confirmation,
            knowledge_searched=knowledge_searched,
            is_first_llm_iteration=is_first_llm_iteration,
            listen_available=listen_available,
            set_fields_available=bool(settable_fields),
            skipped_collects=skipped_collects_for_current_turn(),
            allowed_target_ids=allowed_target_ids,
            activate_tool_available=any(tool.name == TOOL_ACTIVATE for tool in tools),
        )
        messages = self._prompt_constructor.build_messages(context)
        # Observability metadata only: which declared tools were withheld by an
        # inactive gate for this exact call. Resolve the owning skill the same
        # way the schemas and the Inspector's tools panel do (memory_scope
        # falls back to the active flow's skill when the frame carries no
        # skill_id), so the two views cannot disagree.
        scope_skill_id, _ = tracker_handle.memory_scope()
        gated_tool_names = (
            inactive_gated_tool_names(
                self._static_data.skill_catalog,
                scope_skill_id,
                active_target_id,
                memory_values,
            )
            if scope_skill_id
            else []
        )
        return messages, tools, gated_tool_names

    async def _emit_set_memory_button_skip_notice(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        llm_client: LLMClient,
        iteration: int,
    ) -> TurnResult:
        """Tell the user a ``set:`` button tap is not actionable, then end."""
        structlogger.debug(
            "mantle.orchestrator.set_memory_button_skip_notice",
            iteration=iteration,
        )
        # Fill channel ``button_title`` before memory substitution so a real
        # memory entry named ``button_title`` cannot claim the placeholder.
        # The packaged skip utterance does not rephrase: ``button_title`` is
        # untrusted channel input. The raw ``set:`` payload stays out of any
        # later LLM prompt via ``suppress_llm_user_message``.
        resolved = self._skill_executor.resolve_response_name(
            UTTER_SET_MEMORY_BUTTON_SKIPPED,
            tracker_handle,
            substitute_placeholders=False,
        )
        notice_text = substitute_memory_placeholders(
            fill_set_memory_button_skip_notice(resolved.text, turn.metadata),
            tracker_handle,
        )
        skill_id, flow_id = tracker_handle.memory_scope()
        agent_response = AgentResponse(
            text=notice_text,
            mode=ResponseMode.WAIT,
            rephrase=resolved.rephrase,
            response_name=UTTER_SET_MEMORY_BUTTON_SKIPPED,
            buttons=resolved.buttons,
            button_source=resolved.button_source,
            variant_metadata=resolved.variant_metadata,
            **button_source_scope_fields(resolved.button_source, skill_id, flow_id),
        )
        result = await self._process_agent_response(
            agent_response,
            tracker_handle,
            turn,
            llm_client,
            iteration,
        )
        if result is not None:
            return result
        return self._completed_or_cancelled(
            TurnResult(iteration_count=iteration),
            source=_SOURCE_SKIP_SET_MEMORY_BUTTON,
        )

    async def _expand_button_source(
        self,
        response: AgentResponse,
        tracker_handle: TrackerHandle,
    ) -> AgentResponse:
        """Populate ``buttons.source``, aborting if the user barges in.

        Source tools are local Python functions, but a builder may still make
        them slow. Race the lookup against the turn token so a barge-in does
        not wait for that work to finish.
        """
        return await current_turn_context().run_cancellable(
            self._skill_executor.expand_button_source(response, tracker_handle)
        )

    def _should_hold_wait_for_post_activate_fill(
        self,
        agent_response: AgentResponse,
        tracker_handle: TrackerHandle,
    ) -> bool:
        """Return whether to hold this WAIT so a silent ``set_fields`` can run first.

        ``CONTINUE`` and mid-flow canned lines (``completes_current_step`` with
        more script remaining in this flow) keep going as today. Collect asks,
        listen, and a canned line that would pop the current flow are held so
        ``set_fields`` can still write that flow's fields — including when a
        parent frame remains and the turn would CONTINUE after delivery. A
        held listen is a non-completing ``WAIT``. It is deferred before this
        hold, so the step has not advanced and the next lap runs it.
        ``hangup`` commits immediately and is not held.
        """
        if agent_response.mode != ResponseMode.WAIT:
            return False
        # The call is ending, so a value saved now has nothing left to use
        # it, and holding this wait would continue into the step after hangup.
        if self._skill_executor.hangup_requested:
            return False
        if (
            agent_response.completes_current_step
            and not self._skill_executor.completing_delivered_step_ends_active_flow(
                tracker_handle
            )
        ):
            return False
        settable_fields, _ = self._skill_executor.settable_fields_for_turn(
            tracker_handle
        )
        return bool(settable_fields)

    @staticmethod
    def _awaits_tool_confirmation(tracker_handle: TrackerHandle) -> bool:
        """Return whether the active frame is paused on ``requires_confirmation``."""
        return tracker_handle.pending_tool_confirmation_for_active_frame() is not None

    async def _fill_then_resume_held_wait(
        self,
        held_wait: AgentResponse,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        llm_client: LLMClient,
        iteration: int,
    ) -> Optional[TurnResult]:
        """Run the silent fill, then let the next ``advance_steps`` re-decide.

        The held WAIT is not delivered. A now-filled collect can be skipped
        on the next lap. A ``requires_confirmation`` ask was rendered before
        this fill, so its text and pending tool call omit the values just
        written. Drop that unsent handshake. The next lap pauses again and
        renders the question from the updated memory. Cancelling before
        delivery drops the handshake too, so the next turn is not stuck on a
        question the user never heard. A held listen with more script after
        it moves to that step. A listen that would end the flow cancels that
        frame so wrap-up does not take the next turn.

        Returns:
            A ``TurnResult`` when the turn ends, including cancel.
            ``None`` so the caller continues the loop.
        """
        awaits_confirmation = self._awaits_tool_confirmation(tracker_handle)
        result = await self._run_silent_set_fields_after_activate(
            tracker_handle,
            turn,
            llm_client,
            iteration,
        )
        if awaits_confirmation:
            self._drop_unsent_confirmation_handshake(
                tracker_handle, skipped_ask=held_wait
            )
        if result is not None:
            if result.cancelled:
                self._skill_executor.release_deferred_listen(tracker_handle)
            return result
        return None

    async def _run_silent_set_fields_after_activate(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        llm_client: LLMClient,
        iteration: int,
    ) -> Optional[TurnResult]:
        """Ask the model once to extract already-stated settable fields.

        Uses a dedicated extract prompt and a ``set_fields``-only tool list,
        not a main-loop completion. Assistant text is not emitted. Request
        hooks run before the provider call; a request-hook failure does not
        send the prompt. An empty completion, a discarded response, or a
        provider error is success: the held WAIT then resumes.

        Returns:
            A ``TurnResult`` when cancel ends the turn; ``None`` so the
            caller can ``continue`` after a successful, empty, or failed fill.
        """
        settable_fields, settable_descriptions = (
            self._skill_executor.settable_fields_for_turn(tracker_handle)
        )
        set_fields_tools = build_set_fields_tools_for_turn(
            bootstrap=self._static_data,
            settable_fields=settable_fields or None,
            settable_descriptions=settable_descriptions or None,
            active_target_id=tracker_handle.active_flow_id,
        )
        if not set_fields_tools:
            return None

        context = PromptContext(
            tracker=tracker_handle.tracker,
            bootstrap=self._static_data,
            turn=turn,
        )
        messages = self._prompt_constructor.build_set_fields_fill_messages(context)

        try:
            set_fields_completion = await self._call_llm_with_model_hooks(
                llm_client,
                messages,
                tools=set_fields_tools,
                iteration=iteration,
                span_name="llm.set_fields",
                call_type="set_fields",
                trace_hooked_messages=True,
                allow_streaming=False,
            )
        except OperationCancelled:
            return self._cancelled_result(iteration)
        except HookExecutionError as exc:
            structlogger.warning(
                "mantle.orchestrator.set_fields_fill_request_hook_error",
                error_type=type(exc).__name__,
                iteration=iteration,
            )
            return None
        except _MainLlmCallFailed as exc:
            structlogger.warning(
                "mantle.orchestrator.set_fields_fill_llm_error",
                error_type=type(exc.cause).__name__,
                iteration=iteration,
            )
            return None

        # ``cancel()`` inside the completion can win the race and still return
        # a response. The flag is then only noticed on the next iteration,
        # which is too late to release a held listen before that iteration
        # runs it.
        if current_turn_context().is_cancelled:
            return self._cancelled_result(iteration)

        set_fields_calls = [
            tool_call
            for tool_call in set_fields_completion.tool_calls
            if tool_call.tool_name == TOOL_SET_FIELDS
        ]
        if not set_fields_calls:
            return None
        try:
            preflight = await preflight_tool_calls(
                self._static_data.hooks, set_fields_calls
            )
            if preflight.retry is not None:
                return None
            await self._dispatch_tool_calls(
                [
                    tool_call
                    for tool_call in preflight.tool_calls
                    if tool_call.tool_name == TOOL_SET_FIELDS
                ],
                tracker_handle,
                iteration,
            )
        except HookExecutionError as exc:
            structlogger.warning(
                "mantle.orchestrator.set_fields_fill_hook_error",
                error_type=type(exc).__name__,
                iteration=iteration,
            )
        except OperationCancelled:
            return self._cancelled_result(iteration)
        return None

    async def _process_agent_response(
        self,
        agent_response: AgentResponse,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        llm_client: LLMClient,
        iteration: int,
    ) -> Optional[TurnResult]:
        """Handle one deterministic ``AgentResponse``.

        Three outcomes are possible:

        * ``rephrase`` set     — the canned text is reworded by the LLM before
                                 delivery (``NaturalRephrase`` or
                                 ``ConfirmRephrase``). Confirm-rephrase always
                                 ends the turn. Natural rephrase honours
                                 ``complete_delivered_step`` like verbatim
                                 delivery: ``WAIT`` returns a ``TurnResult``,
                                 ``CONTINUE`` returns ``None``.
        * ``mode=WAIT``           — the text is emitted verbatim and the turn ends;
                                    returns a completed ``TurnResult``.
        * ``mode=CONTINUE``       — the text is emitted verbatim but more phases or
                                    an LLM call must follow; returns ``None`` so the
                                    caller can ``continue`` the iteration loop.
        """
        try:
            agent_response = await self._expand_button_source(
                agent_response,
                tracker_handle,
            )
        except OperationCancelled:
            return self._cancelled_result(iteration)
        structlogger.debug(
            "mantle.orchestrator.pre_llm_response",
            text_preview=agent_response.text[:80],
            mode=agent_response.mode.value,
            rephrase=agent_response.rephrase is not None,
            rephrase_kind=rephrase_kind_label(agent_response.rephrase),
            iteration=iteration,
        )

        if isinstance(agent_response.rephrase, ConfirmRephrase):
            return await self._run_confirm_rephrase_call(
                agent_response,
                tracker_handle,
                turn,
                llm_client,
                iteration,
            )

        if isinstance(agent_response.rephrase, NaturalRephrase):
            return await self._run_rephrase_call(
                agent_response.text,
                tracker_handle,
                turn,
                llm_client,
                iteration,
                response_name=agent_response.response_name,
                completes_current_step=agent_response.completes_current_step,
                buttons=agent_response.buttons,
                variant_metadata=agent_response.variant_metadata,
            )

        if agent_response.text:
            await current_turn_context().send(
                agent_response.text,
                response_name=agent_response.response_name,
                buttons=agent_response.buttons,
                variant_metadata=agent_response.variant_metadata,
            )

        mode = agent_response.mode
        if agent_response.completes_current_step:
            if current_turn_context().is_cancelled:
                return self._cancelled_result(iteration)
            # The executor left the frame on the producing step so the
            # message could be delivered first; complete it now (its
            # completion events land after the BotUttered) and let the
            # post-completion stack decide how the turn proceeds.
            mode = self._skill_executor.complete_delivered_step(tracker_handle)

        if mode == ResponseMode.WAIT:
            return self._completed_or_cancelled(
                TurnResult(
                    iteration_count=iteration,
                    hangup_requested=self._skill_executor.hangup_requested is True,
                ),
                source=_SOURCE_PHASE_RESPONSE_WAIT,
            )

        return None  # CONTINUE — caller loops again

    async def _run_rephrase_call(
        self,
        text_to_rephrase: str,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        llm_client: LLMClient,
        iteration: int,
        *,
        response_name: Optional[str] = None,
        completes_current_step: bool = False,
        buttons: tuple[ResponseButton, ...] = (),
        variant_metadata: Optional[dict[str, Any]] = None,
    ) -> Optional[TurnResult]:
        """Reword and emit a canned response, then wait or continue.

        Delivery is delegated to :meth:`_rephrase_and_send`; this wrapper
        preserves the response's terminal behavior unless completing its
        producing step reveals more work.

        When ``completes_current_step`` is ``True``, the producing step is
        advanced after delivery and the residual stack decides whether the
        turn waits or continues, matching the verbatim path.
        """
        completion_source, cancelled_result = await self._rephrase_and_send(
            text_to_rephrase,
            tracker_handle,
            turn,
            llm_client,
            iteration,
            response_name=response_name,
            buttons=buttons,
            variant_metadata=variant_metadata,
        )
        if cancelled_result is not None:
            return cancelled_result

        mode = ResponseMode.WAIT
        if completes_current_step:
            mode = self._skill_executor.complete_delivered_step(tracker_handle)

        if mode == ResponseMode.CONTINUE:
            return None

        return self._completed_or_cancelled(
            TurnResult(iteration_count=iteration + 1),
            source=completion_source,
        )

    async def _rephrase_and_send(
        self,
        text_to_rephrase: str,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        llm_client: LLMClient,
        iteration: int,
        *,
        response_name: Optional[str] = None,
        buttons: tuple[ResponseButton, ...] = (),
        variant_metadata: Optional[dict[str, Any]] = None,
    ) -> Tuple[str, Optional[TurnResult]]:
        """Ask the LLM to reword a canned response and emit the result.

        This operation does not otherwise end the turn. Callers retain control
        of WAIT versus CONTINUE behavior.

        The prompt is built via ``build_rephrase_messages`` which instructs the
        LLM to preserve meaning while rephrasing *text_to_rephrase* naturally.
        When the rephrase call fails or returns no text, the original canned
        *text_to_rephrase* is delivered verbatim so the user still hears the
        approved response.
        """
        active_target_id = tracker_handle.active_flow_id
        context = PromptContext(
            tracker=tracker_handle.tracker,
            bootstrap=self._static_data,
            turn=turn,
            active_target=(
                self._static_data.skill_catalog.resolve_activation_target(
                    active_target_id
                )
                if active_target_id
                else None
            ),
            active_skill_id=tracker_handle.active_skill_id,
        )
        messages = self._prompt_constructor.build_rephrase_messages(
            context, text_to_rephrase
        )

        rephrase_completion: Optional[_HookedLlmCompletion] = None
        llm_failed = False
        try:
            rephrase_completion = await self._call_llm_with_model_hooks(
                llm_client,
                messages,
                tools=None,
                iteration=iteration,
                span_name="llm.rephrase",
                call_type="rephrase",
                span_input=text_to_rephrase,
                allow_streaming=True,
            )
        except OperationCancelled:
            return "", self._cancelled_result(iteration)
        except HookExecutionError as exc:
            llm_failed = True
            structlogger.warning(
                "mantle.orchestrator.rephrase_request_hook_error",
                error_type=type(exc).__name__,
                iteration=iteration,
            )
        except _MainLlmCallFailed as exc:
            llm_failed = True
            structlogger.warning(
                "mantle.orchestrator.rephrase_llm_error",
                error=str(exc.cause),
                error_type=type(exc.cause).__name__,
                iteration=iteration,
            )

        llm_text = (
            ""
            if rephrase_completion is None or rephrase_completion.discarded
            else (rephrase_completion.text or "")
        )
        if rephrase_completion is not None and llm_text:
            structlogger.debug(
                "mantle.orchestrator.rephrase_response",
                original_preview=text_to_rephrase[:80],
                rephrased_preview=llm_text[:80],
                iteration=iteration,
            )
            await self._emit_llm_text(
                llm_text,
                rephrase_completion.response,
                response_name=response_name,
                response_source=ResponseSource.REPHRASED,
                buttons=buttons,
                variant_metadata=variant_metadata,
                streamed=rephrase_completion.streamed,
            )
            completion_source = _SOURCE_REPHRASE_TEXT
        else:
            if not llm_failed:
                structlogger.warning(
                    "mantle.orchestrator.rephrase_yielded_no_text",
                    iteration=iteration,
                    has_tool_calls=bool(
                        rephrase_completion is not None
                        and rephrase_completion.response.tool_calls
                    ),
                )
            structlogger.info(
                "mantle.orchestrator.rephrase_fallback_to_verbatim",
                iteration=iteration,
            )
            await current_turn_context().send(
                text_to_rephrase,
                response_name=response_name,
                response_source=ResponseSource.VERBATIM,
                buttons=buttons,
                variant_metadata=variant_metadata,
            )
            completion_source = _SOURCE_REPHRASE_FALLBACK

        if current_turn_context().is_cancelled:
            return "", self._cancelled_result(iteration)

        return completion_source, None

    async def _run_confirm_rephrase_call(
        self,
        agent_response: AgentResponse,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        llm_client: LLMClient,
        iteration: int,
    ) -> TurnResult:
        """Rephrase a filled collect ask as a confirmation question.

        On LLM failure or empty output, falls back to the canned ask text so
        the confirmation gate is preserved.
        """
        active_target_id = tracker_handle.active_flow_id
        context = PromptContext(
            tracker=tracker_handle.tracker,
            bootstrap=self._static_data,
            turn=turn,
            active_target=(
                self._static_data.skill_catalog.resolve_activation_target(
                    active_target_id
                )
                if active_target_id
                else None
            ),
            active_skill_id=tracker_handle.active_skill_id,
        )
        confirm = agent_response.rephrase
        if not isinstance(confirm, ConfirmRephrase):
            raise TypeError("confirm-rephrase call requires ConfirmRephrase payload")
        messages = self._prompt_constructor.build_confirm_rephrase_messages(
            context,
            agent_response.text,
            field_name=confirm.field,
            value=confirm.value,
            field_description=confirm.field_description,
        )

        try:
            confirm_completion = await self._call_llm_with_model_hooks(
                llm_client,
                messages,
                tools=None,
                iteration=iteration,
                span_name="llm.confirm_rephrase",
                call_type="confirm_rephrase",
                span_input=agent_response.text,
                allow_streaming=True,
            )
        except (OperationCancelled, HookExecutionError, _MainLlmCallFailed) as exc:
            cause = exc.cause if isinstance(exc, _MainLlmCallFailed) else exc
            structlogger.warning(
                "mantle.orchestrator.confirm_rephrase_failed",
                iteration=iteration,
                error_type=type(cause).__name__,
            )
            await current_turn_context().send(
                agent_response.text,
                response_name=agent_response.response_name,
                response_source=ResponseSource.VERBATIM,
                buttons=agent_response.buttons,
                variant_metadata=agent_response.variant_metadata,
            )
            return self._completed_or_cancelled(
                TurnResult(iteration_count=iteration + 1),
                source=_SOURCE_CONFIRM_REPHRASE_FALLBACK,
            )

        response = confirm_completion.response
        llm_text = (
            "" if confirm_completion.discarded else (confirm_completion.text or "")
        )
        if not llm_text:
            structlogger.warning(
                "mantle.orchestrator.confirm_rephrase_yielded_no_text",
                iteration=iteration,
                has_tool_calls=bool(response and response.tool_calls),
            )
            await current_turn_context().send(
                agent_response.text,
                response_name=agent_response.response_name,
                response_source=ResponseSource.VERBATIM,
                buttons=agent_response.buttons,
                variant_metadata=agent_response.variant_metadata,
            )
            return self._completed_or_cancelled(
                TurnResult(iteration_count=iteration + 1),
                source=_SOURCE_CONFIRM_REPHRASE_FALLBACK,
            )

        structlogger.debug(
            "mantle.orchestrator.confirm_rephrase_response",
            original_preview=agent_response.text[:80],
            rephrased_preview=llm_text[:80],
            iteration=iteration,
        )
        await self._emit_llm_text(
            llm_text,
            response,
            response_name=agent_response.response_name,
            response_source=ResponseSource.REPHRASED,
            buttons=agent_response.buttons,
            variant_metadata=agent_response.variant_metadata,
            streamed=confirm_completion.streamed,
        )
        return self._completed_or_cancelled(
            TurnResult(iteration_count=iteration + 1),
            source=_SOURCE_CONFIRM_REPHRASE_TEXT,
        )

    async def _call_main_llm_with_empty_retry(
        self,
        llm_client: LLMClient,
        messages: List[LlmMessage],
        tools: Optional[List[AgentToolSchema]],
        gated_tool_names: Optional[List[str]],
        *,
        model_settings: Optional[Dict[str, Any]] = None,
        iteration: int,
        allow_streaming: bool = True,
    ) -> LLMResponse:
        """Call the main LLM, retrying immediately on empty completions.

        Empty means neither text nor tool calls. Retries use the same messages,
        tools, and model settings and do not consume an extra turn-loop
        iteration.

        Raises:
            OperationCancelled: When cancel wins before a retry attempt.
            _MainLlmCallFailed: When the provider call fails (span-update
                failures are not wrapped — they propagate as-is).
        """
        attempt = 0
        response = await self._call_main_llm_once(
            llm_client,
            messages,
            tools,
            gated_tool_names,
            model_settings=model_settings,
            iteration=iteration,
            attempt=attempt,
            allow_streaming=allow_streaming,
        )
        while _is_empty_llm_response(response):
            # Include cancel and a barge-in in ``will_retry`` so telemetry matches
            # control flow: once the user has the floor, their input comes next
            # and another attempt would only be withheld.
            will_retry = (
                attempt + 1 < _MAX_EMPTY_LLM_ATTEMPTS
                and not current_turn_context().is_cancelled
                and not current_turn_context().is_interrupted
            )
            structlogger.warning(
                "mantle.orchestrator.empty_llm_response",
                iteration=iteration,
                attempt=attempt,
                max_attempts=_MAX_EMPTY_LLM_ATTEMPTS,
                will_retry=will_retry,
            )
            if not will_retry:
                if current_turn_context().is_cancelled:
                    raise OperationCancelled()
                break
            attempt += 1
            response = await self._call_main_llm_once(
                llm_client,
                messages,
                tools,
                gated_tool_names,
                model_settings=model_settings,
                iteration=iteration,
                attempt=attempt,
                allow_streaming=allow_streaming,
            )
        return response

    async def _call_main_llm_once(
        self,
        llm_client: LLMClient,
        messages: List[LlmMessage],
        tools: Optional[List[AgentToolSchema]],
        gated_tool_names: Optional[List[str]],
        *,
        model_settings: Optional[Dict[str, Any]] = None,
        iteration: int,
        attempt: int,
        allow_streaming: bool = True,
    ) -> LLMResponse:
        """Make a single main LLM call and record it as a span.

        Raises:
            OperationCancelled: When cancel wins the race for the call.
            _MainLlmCallFailed: When the provider call fails. Span recording
                stays outside the ``except`` so serialization errors are not
                misclassified as LLM call failures.
        """
        with langfuse_span(
            name="llm.main",
            metadata={
                "call_type": "main",
                "iteration": iteration,
                "tool_count": len(tools or []),
                "attempt": attempt,
            },
            span_input=messages,
        ) as span:
            try:
                response = await self._call_llm(
                    llm_client,
                    messages,
                    tools=tools,
                    gated_tool_names=gated_tool_names,
                    allow_streaming=allow_streaming,
                    model_settings=model_settings,
                )
            except OperationCancelled:
                raise
            except Exception as exc:
                raise _MainLlmCallFailed(exc) from exc
            span.update(output=_llm_response_output(response))
            return response

    async def _call_llm_with_model_hooks(
        self,
        llm_client: LLMClient,
        messages: List[LlmMessage],
        *,
        tools: Optional[List[AgentToolSchema]],
        iteration: int,
        span_name: str,
        call_type: str,
        allow_streaming: bool,
        span_input: Any = None,
        trace_hooked_messages: bool = False,
    ) -> _HookedLlmCompletion:
        """Run request hooks, one completion, then response hooks.

        Quiet calls (rephrase, confirm-rephrase, post-activate ``set_fields``)
        share this path so a ``modify_model_request`` redaction runs before the
        provider sees the prompt. A request-hook crash raises
        ``HookExecutionError`` and does not call the provider.

        ``RetryModel`` from ``modify_model_response`` sets ``discarded`` and
        clears text and tool calls. It does not start another iteration.
        Response-hook crashes stay fail-open inside
        ``apply_model_response_hooks``.

        A registered response modifier, or a tool-call modifier when tools are
        offered, forces a buffered completion so rewritten text is not already
        spoken.

        Args:
            llm_client: Provider client for this turn.
            messages: Prompt built for this quiet call, before request hooks.
            tools: Tool schemas offered on this call. ``None`` for rephrase.
            iteration: Turn-loop iteration, forwarded to request hooks.
            span_name: Langfuse span name, such as ``llm.rephrase``.
            call_type: Span metadata value, such as ``rephrase``.
            allow_streaming: Whether this call may stream when no modifier
                forces buffering. The fill call passes ``False``.
            span_input: Value recorded on the span. Ignored when
                ``trace_hooked_messages`` is set.
            trace_hooked_messages: Record the post-request-hook messages as
                the span input, so a redaction is what the trace stores.

        Returns:
            The provider response plus the post-response-hook text and tool
            calls. ``discarded`` is set when the response hook asked for a
            retry. ``streamed`` is set when tokens may already have reached
            the user.

        Raises:
            HookExecutionError: The request hook failed closed before the
                provider call.
            OperationCancelled: The turn was cancelled during the completion.
            _MainLlmCallFailed: The provider call failed. Span-output errors
                are recorded after that handler and propagate as themselves.
        """
        messages, model_settings = await apply_model_request_hooks(
            self._static_data.hooks,
            messages,
            tools,
            iteration=iteration,
        )
        hooks = self._static_data.hooks
        if hooks.modifier(POINT_MODEL_RESPONSE) is not None or (
            tools and hooks.modifier(POINT_TOOL_CALL) is not None
        ):
            allow_streaming = False
        recorded_input = messages if trace_hooked_messages else span_input

        with langfuse_span(
            name=span_name,
            metadata={"call_type": call_type, "iteration": iteration},
            span_input=recorded_input,
        ) as span:
            try:
                response = await self._call_llm(
                    llm_client,
                    messages,
                    tools=tools,
                    model_settings=model_settings or None,
                    allow_streaming=allow_streaming,
                )
            except OperationCancelled:
                raise
            except Exception as exc:
                raise _MainLlmCallFailed(exc) from exc
            span.update(output=_llm_response_output(response))

        hooked = await apply_model_response_hooks(
            self._static_data.hooks,
            text=response.response_text(),
            tool_calls=list(response.tool_calls or []),
            latency_ms=response.latency_ms,
        )
        if hooked.retry is not None:
            return _HookedLlmCompletion(
                response=response,
                text=None,
                tool_calls=[],
                discarded=True,
                streamed=allow_streaming,
            )
        return _HookedLlmCompletion(
            response=response,
            text=hooked.text,
            tool_calls=list(hooked.tool_calls),
            discarded=False,
            streamed=allow_streaming,
        )

    @observe_llm_call
    async def _call_llm(
        self,
        llm_client: LLMClient,
        messages: List[LlmMessage],
        tools: Optional[List[AgentToolSchema]] = None,
        gated_tool_names: Optional[List[str]] = None,
        model_settings: Optional[Dict[str, Any]] = None,
        *,
        allow_streaming: bool = True,
    ) -> LLMResponse:
        """Invoke the LLM, buffering when response or tool-call modifiers require it.

        A registered ``modify_model_response`` or ``modify_tool_call`` hook
        forces a buffered completion so hooks can rewrite or discard before
        any tokens reach the user. Callers pass ``allow_streaming=False`` in
        that case. Otherwise this streams token chunks when the channel
        supports it.

        Both paths go through ``LLMClient`` so ``mantle.llm.request`` (with
        the formatted prompt) is logged whether or not the channel streams.

        The await is raced against the turn cancellation token so call teardown
        aborts an in-flight completion instead of waiting for it to finish.
        Raises :exc:`~rasa.agents.core.cancellation.OperationCancelled` when
        cancel wins.

        ``gated_tool_names`` is not consumed here — it rides along for the
        ``observe_llm_call`` decorator, which records every completion in the
        conversation's ephemeral call log (the Inspector's stopgap for the
        GenAI span channel, ENG-3003).

        Canonical ``AgentToolSchema`` tools are converted to LiteLLM/OpenAI
        JSON immediately before the provider call.
        """
        litellm_tools = emit_litellm_tools(tools) if tools else None
        ctx = current_turn_context()
        if allow_streaming and caller_requested_streaming(ctx.output_channel):
            return await ctx.run_cancellable(
                llm_client.acompletion_streaming(
                    messages,
                    ctx.llm_streaming_output_channel,
                    ctx.sender_id,
                    tools=litellm_tools,
                    model_settings=model_settings,
                    response_event_id=ctx.begin_streamed_response(),
                )
            )
        return await ctx.run_cancellable(
            llm_client.acompletion(
                messages, tools=litellm_tools, model_settings=model_settings
            )
        )

    async def _emit_llm_text(
        self,
        llm_text: str,
        response: LLMResponse,
        *,
        is_filler: bool = False,
        response_name: Optional[str] = None,
        response_source: Optional[str] = None,
        buttons: tuple[ResponseButton, ...] = (),
        variant_metadata: Optional[dict[str, Any]] = None,
        streamed: bool = True,
    ) -> None:
        """Deliver LLM text to the user and tracker (streamed or blocking).

        After streamed text, buttons are emitted separately without repeating
        the text so streaming channels can render the authored actions.

        Pass ``streamed=False`` when the completion was fetched with streaming
        disabled (for example a ``modify_model_response`` or ``modify_tool_call``
        modifier forced buffering): no tokens reached the user, so text is sent
        in full via :meth:`MessageTurnContext.send`.
        """
        ctx = current_turn_context()
        if streamed and caller_requested_streaming(ctx.output_channel):
            # Streaming provides first-token and total-generation timings.
            await ctx.record_streamed_message(
                llm_text,
                is_filler=is_filler,
                llm_time_to_first_token_ms=response.llm_time_to_first_token_ms,
                llm_total_time_ms=response.latency_ms,
                response_name=response_name,
                response_source=response_source,
                buttons=buttons,
                variant_metadata=variant_metadata,
            )
            return
        # Non-streaming (or buffered on a streaming channel) provides only
        # total-generation timing.
        await ctx.send(
            llm_text,
            is_filler=is_filler,
            response_name=response_name,
            response_source=response_source,
            llm_total_time_ms=response.latency_ms,
            buttons=buttons,
            variant_metadata=variant_metadata,
        )

    async def _emit_hangup_goodbye(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        llm_client: LLMClient,
        iteration: int,
    ) -> Optional[TurnResult]:
        """Emit the builder-overridable farewell before a bare hangup call.

        Honours ``metadata.rephrase`` on ``utter_hangup_goodbye`` the same way
        other canned responses do. Returns a cancelled result when teardown
        aborts rephrase; otherwise ``None``.
        """
        resolved = self._skill_executor.resolve_response_name(
            _UTTER_HANGUP_GOODBYE,
            tracker_handle,
        )
        if isinstance(resolved.rephrase, NaturalRephrase):
            _, cancelled_result = await self._rephrase_and_send(
                resolved.text,
                tracker_handle,
                turn,
                llm_client,
                iteration,
                response_name=_UTTER_HANGUP_GOODBYE,
                buttons=resolved.buttons,
                variant_metadata=resolved.variant_metadata,
            )
            return cancelled_result
        await current_turn_context().send(
            resolved.text,
            response_name=_UTTER_HANGUP_GOODBYE,
            buttons=resolved.buttons,
            variant_metadata=resolved.variant_metadata,
        )
        return None

    async def _handle_llm_response(
        self,
        llm_text: Optional[str],
        tool_calls: List[LLMToolCall],
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        llm_client: LLMClient,
        iteration: int,
        llm_response: LLMResponse,
        listen_available: bool,
        knowledge_searched: bool = False,
        streamed: bool = True,
    ) -> Optional[TurnResult]:
        """Route one LLM response to the correct outcome path.

        Returns a ``TurnResult`` to stop the turn, or ``None`` to continue
        (tools were dispatched, next iteration should follow).

        Response shapes handled:
        - Text only → emit and end turn.
        - ``listen`` alone (no text, no other tools) → do not emit; dispatch
          listen; end turn (same wait as text-only). If listen was withheld
          for this call, drop it and follow the empty-response path instead.
        - ``listen`` mixed with text or other tools → drop ``listen`` and
          follow the matching shape below.
        - Text + tools → emit text, dispatch tools (stop if any tool says WAIT).
        - Tools only → dispatch tools (stop if any tool says WAIT).
        - Empty → error. A barge-in that lands on withheld listen (stripped
          to empty) reports cancelled instead.

        When *knowledge_searched* is set, a text-only answer that lands with a
        skill still active parks that skill and offers to resume it, mirroring
        how a digression re-anchors the user — the turn then continues so the
        resume prompt is uttered instead of ending.

        Rephrase responses never reach this method — they are handled earlier
        in the turn loop by ``_run_rephrase_call``.

        *streamed* reflects whether this completion's tokens already reached
        the user (``False`` when the main call was buffered for response or
        tool-call hooks).
        """
        # Mixed listen is ignored: text already ends the turn, other tools
        # still need to run. Strip it first so the branches below stay unchanged.
        remaining_calls = _tools_without_listen(tool_calls)
        # listen-only (no text, and every call is listen): silent wait.
        # Withheld listen is stripped instead so collect / confirmation /
        # post-search cannot be skipped when the model still emits listen.
        # Empty (no text, no tools) must fall through to the empty-response error.
        if listen_available and not llm_text and tool_calls and not remaining_calls:
            if current_turn_context().is_cancelled:
                return self._cancelled_result(iteration)
            try:
                await self._dispatch_tool_calls(tool_calls, tracker_handle, iteration)
            except HookExecutionError as exc:
                return await self._hook_error_result(
                    exc,
                    iteration,
                    response_name=UTTER_TOOL_CALL_HOOK_ERROR,
                )
            except OperationCancelled:
                return self._cancelled_result(iteration)
            return self._completed_or_cancelled(
                TurnResult(iteration_count=iteration + 1),
                source=_SOURCE_LLM_LISTEN,
            )
        tool_calls = remaining_calls
        hangup_in_batch = any(
            tool_call.tool_name == TOOL_HANGUP for tool_call in tool_calls
        )
        # After stripping withheld listen this looks empty. Cancellation or a
        # barge-in is not an LLM error: once the user has the floor, their input
        # comes next.
        ctx = current_turn_context()
        if (ctx.is_cancelled or ctx.is_interrupted) and not llm_text and not tool_calls:
            return self._cancelled_result(iteration)

        # Text-only: emit, then either offer to resume a parked skill or end.
        if llm_text and not tool_calls:
            structlogger.debug(
                "mantle.orchestrator.text_response",
                text_preview=llm_text[:80],
            )
            await self._emit_llm_text(llm_text, llm_response, streamed=streamed)
            # After answering an informational search_knowledge query, re-anchor
            # to the interrupted skill (if any). The decision (should we park?) is
            # kept separate from the stack mutation (do the parking) so the
            # condition below has no side effects. When a skill is parked, continue
            # the loop so advance_steps utters the resume prompt this turn.
            if (
                knowledge_searched
                and not current_turn_context().is_cancelled
                and self._skill_executor.should_park_active_skill(tracker_handle)
            ):
                self._skill_executor.park_active_skill_and_offer_resume(tracker_handle)
                return None
            return self._completed_or_cancelled(
                TurnResult(iteration_count=iteration + 1),
                source=_SOURCE_LLM_TEXT,
            )

        # Text + tools (no hangup): emit text as a filler before the tools run.
        # Hangup farewells are deferred until after dispatch so a confirmation
        # ask/denial that clears hangup does not speak goodbye first.
        deferred_hangup_text: Optional[str] = None
        if llm_text and tool_calls:
            structlogger.debug(
                "mantle.orchestrator.text_with_tools",
                text_preview=llm_text[:80],
                tool_count=len(tool_calls),
            )
            if hangup_in_batch:
                deferred_hangup_text = llm_text
            else:
                await self._emit_llm_text(
                    llm_text,
                    llm_response,
                    is_filler=True,
                    streamed=streamed,
                )

        # Empty response: neither text nor tool calls. Warnings for empty
        # attempts (including exhaustion) are owned by
        # ``_call_main_llm_with_empty_retry`` so the final empty is not
        # double-logged here.
        if not tool_calls:
            return self._completed(
                TurnResult(
                    error="LLM returned an empty response",
                    iteration_count=iteration + 1,
                ),
                source=_SOURCE_EMPTY_LLM_RESPONSE,
            )

        if current_turn_context().is_cancelled:
            return self._cancelled_result(iteration)

        # Dispatch all tool calls; next iteration handles any phase responses.
        # Tool-call hooks already preflighted this batch in ``run_turn`` so
        # routing and the knowledge_searched latch see rewritten names.
        try:
            await self._dispatch_tool_calls(tool_calls, tracker_handle, iteration)
        except HookExecutionError as exc:
            return await self._hook_error_result(
                exc,
                iteration,
                response_name=UTTER_TOOL_CALL_HOOK_ERROR,
            )
        except OperationCancelled:
            return self._cancelled_result(iteration)
        # A tool with requires_confirmation writes an awaiting_confirmation
        # result and queues a WAIT ask — end the turn so the user can answer
        # before the LLM continues. resolve(false) queues a WAIT denial for the
        # same reason. Drain activate/when/outcome utters queued earlier in the
        # same batch first so a confirmation WAIT does not strand them.
        queued_result = await self._emit_queued_verbatim_responses(
            tracker_handle,
            turn,
            llm_client,
            iteration,
        )
        if queued_result is not None:
            self._skill_executor.clear_hangup_request()
            self._drop_unsent_confirmation_handshake(tracker_handle)
            return queued_result
        confirmation_ask = self._skill_executor.consume_confirmation_ask()
        if confirmation_ask is not None:
            self._skill_executor.clear_hangup_request()
            await self._record_cancelled_hangup_farewell_if_streamed(
                deferred_hangup_text, llm_response, streamed=streamed
            )
            result = await self._process_agent_response(
                confirmation_ask,
                tracker_handle,
                turn,
                llm_client,
                iteration,
            )
            # Same as the advance_steps path: clear pending when the ask never
            # reached the user (muted after a barge-in, or an outgoing-text
            # rejection). A delivered ask stays so the next turn can resolve.
            if result is not None and not self._confirmation_ask_was_delivered(
                tracker_handle, confirmation_ask
            ):
                tracker_handle.clear_pending_tool_confirmation()
            return result
        confirmation_denial = self._skill_executor.consume_confirmation_denial()
        if confirmation_denial is not None:
            self._skill_executor.clear_hangup_request()
            await self._record_cancelled_hangup_farewell_if_streamed(
                deferred_hangup_text, llm_response, streamed=streamed
            )
            return await self._process_agent_response(
                confirmation_denial,
                tracker_handle,
                turn,
                llm_client,
                iteration,
            )
        if self._skill_executor.hangup_requested is True:
            if deferred_hangup_text is not None:
                await self._emit_llm_text(
                    deferred_hangup_text,
                    llm_response,
                    is_filler=False,
                    streamed=streamed,
                )
            elif hangup_in_batch and not llm_text:
                structlogger.debug("mantle.orchestrator.hangup_without_goodbye")
                cancelled = await self._emit_hangup_goodbye(
                    tracker_handle, turn, llm_client, iteration
                )
                if cancelled is not None:
                    return cancelled
            return self._completed_or_cancelled(
                TurnResult(iteration_count=iteration + 1, hangup_requested=True),
                source=_SOURCE_LLM_HANGUP,
            )
        return None

    async def _record_cancelled_hangup_farewell_if_streamed(
        self,
        deferred_hangup_text: Optional[str],
        llm_response: LLMResponse,
        *,
        streamed: bool,
    ) -> None:
        """Record a deferred hangup farewell only when tokens already streamed.

        Confirmation cancels hangup, so a non-streamed farewell must stay
        suppressed. Streamed channels may already have played the tokens during
        the LLM call — record them as filler so the tracker matches audio.
        """
        if deferred_hangup_text is None or not streamed:
            return
        if not caller_requested_streaming(current_turn_context().output_channel):
            return
        await self._emit_llm_text(
            deferred_hangup_text,
            llm_response,
            is_filler=True,
            streamed=True,
        )

    def _confirmation_ask_was_delivered(
        self, tracker_handle: TrackerHandle, ask: AgentResponse
    ) -> bool:
        """Check whether *ask* already produced a ``BotUttered`` the user heard.

        A recorded question keeps pending confirmation available even when a
        barge-in cut it off. One recorded while the user had the floor was
        never played, so it does not count: the user's next words must not
        answer a question they did not hear. Only events after the latest
        ``UserUttered`` count — an earlier turn's same template must not look
        like this ask was delivered.
        """
        response_name = ask.response_name
        canned_text = ask.text
        for event in reversed(tracker_handle.tracker.events):
            if isinstance(event, UserUttered):
                return False
            if not isinstance(event, BotUttered):
                continue
            if is_discarded_utterance(event):
                continue
            metadata = event.metadata or {}
            if metadata.get(RESPONSE_UNHEARD_METADATA_KEY):
                continue
            if (
                response_name is not None
                and metadata.get(UTTER_ACTION_METADATA_KEY) == response_name
            ):
                return True
            if event.text == canned_text:
                return True
        return False

    def _drop_unsent_confirmation_handshake(
        self,
        tracker_handle: TrackerHandle,
        skipped_ask: Optional[AgentResponse] = None,
    ) -> None:
        """Abort a confirmation ask that never reached the user.

        A cancelled queued rephrase, or an outgoing-text rejection of the ask,
        returns before the user hears the question. Consume a leftover executor
        ask so it cannot leak. Ordered-block ``execute_tool`` already consumed
        the ask into ``advance_steps``'s response, so *skipped_ask* is that
        unsent WAIT payload.
        """
        leftover_ask = self._skill_executor.consume_confirmation_ask()
        pending = tracker_handle.pending_tool_confirmation
        if leftover_ask is not None:
            tracker_handle.clear_pending_tool_confirmation()
            return
        if (
            skipped_ask is None
            or pending is None
            or skipped_ask.mode != ResponseMode.WAIT
        ):
            return
        if (
            pending.confirmation_ask is not None
            and skipped_ask.text != pending.confirmation_ask
            and pending.execute_step_id is None
        ):
            return
        tracker_handle.clear_pending_tool_confirmation()

    async def _emit_queued_verbatim_responses(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        llm_client: LLMClient,
        iteration: int,
    ) -> Optional[TurnResult]:
        """Send queued outcome/trigger responses in authored order.

        Opted-in items are reworded one at a time via
        :meth:`_rephrase_and_send`; others are sent verbatim. This path does
        not end the turn. Cancellation during button-source expansion or a
        rephrase aborts remaining queued items and returns a cancelled result.
        """
        for queued_response in self._skill_executor.consume_verbatim_responses():
            try:
                queued_response = await self._expand_button_source(
                    queued_response,
                    tracker_handle,
                )
            except OperationCancelled:
                return self._cancelled_result(iteration)
            if not queued_response.text:
                continue
            structlogger.debug(
                "mantle.orchestrator.queued_response",
                response_name=queued_response.response_name,
                rephrase=queued_response.rephrase is not None,
                rephrase_kind=rephrase_kind_label(queued_response.rephrase),
                iteration=iteration,
            )
            if isinstance(queued_response.rephrase, NaturalRephrase):
                _, cancelled_result = await self._rephrase_and_send(
                    queued_response.text,
                    tracker_handle,
                    turn,
                    llm_client,
                    iteration,
                    response_name=queued_response.response_name,
                    buttons=queued_response.buttons,
                    variant_metadata=queued_response.variant_metadata,
                )
                if cancelled_result is not None:
                    return cancelled_result
            else:
                await current_turn_context().send(
                    queued_response.text,
                    response_name=queued_response.response_name,
                    buttons=queued_response.buttons,
                    variant_metadata=queued_response.variant_metadata,
                )
        return None

    async def _dispatch_tool_calls(
        self,
        tool_calls: List[LLMToolCall],
        tracker_handle: TrackerHandle,
        iteration: int,
    ) -> None:
        """Dispatch all tool calls and persist results on the tracker.

        Caller must already have run ``preflight_tool_calls`` on *tool_calls*
        (in ``run_turn``) so listen-only routing and the ``knowledge_searched``
        latch use post-hook names. Confirmation and tool-constraint gates still
        run inside ``SkillExecutor.dispatch_tool_call``. Confirmation resume,
        settable writes, and correction replay do not enter this method and
        therefore do not invoke tool-call hooks.

        After each successful dispatch, ``on_tool_result`` /
        ``modify_tool_result`` may rewrite the persisted result (fail-open).
        Tool-call ids and batch metadata are preserved.

        Tool calls are state transitions (memory writes, flow activation /
        completion, custom ``@tool`` functions). A tool with
        ``requires_confirmation`` also queues a user-facing WAIT ask that the
        caller emits after this method returns. Decline via
        ``resolve_tool_confirmation(false)`` queues a WAIT denial the same way.
        All calls in the batch are still dispatched so each ``tool_call_id``
        gets a result (the paused tool receives an ``awaiting_confirmation``
        payload). Text the agent should send outside confirmation WAIT paths is
        produced by ``SkillExecutor.advance_steps`` on the next iteration.

        Each dispatch is raced against the turn cancellation token so call
        teardown aborts an in-flight tool / skill call promptly. Remaining tools
        in the batch are not started after cancel. A voice barge-in does not
        cancel: the batch finishes and new input is taken in afterwards.

        ``ToolResult.next`` instructions returned by tools in the batch run
        once, in queue order, after every call in the batch has dispatched and
        its events are on the tracker. The whole batch therefore runs against
        the skill state the LLM planned it for. A call whose result a hook
        turned into an error contributes no instructions. On cancellation
        nothing is applied; the next turn discards the queue.

        Each dispatch writes a ``ToolExecuted`` event with replay metadata, so
        later iterations rebuild one native OpenAI tool message from the tracker.
        """
        if not tool_calls:
            return

        # Anchor the batch id to the model's emission order before hangup is
        # moved last for dispatch.
        tool_batch_id = f"{iteration}-{tool_calls[0].id}"
        tool_calls = _hangup_last(tool_calls)
        ctx = current_turn_context()
        next_instructions: List[PendingInstruction] = []

        for tc in tool_calls:
            if ctx.is_cancelled:
                raise OperationCancelled()
            structlogger.info(
                "mantle.tool.dispatched",
                tool_name=tc.tool_name,
                iteration=iteration,
            )
            # Input mirrors ``dispatch_tool_call`` (name + args) without
            # argument values, which can hold PII. Iteration and count stay
            # in metadata for filtering. Span output is the *post-hook*
            # persisted result so redaction reaches traces, not only the
            # tracker / next prompt.
            with langfuse_span(
                name="tool_call",
                metadata={
                    "iteration": iteration,
                    "argument_count": len(tc.tool_args),
                },
                span_input={
                    "tool_name": tc.tool_name,
                    "tool_args": sorted(tc.tool_args.keys()),
                },
            ) as span:
                stack_before = _stack_signature(tracker_handle)
                raw_result = await ctx.run_cancellable(
                    self._skill_executor.dispatch_tool_call(
                        tool_name=tc.tool_name,
                        tool_args=tc.tool_args,
                        tracker_handle=tracker_handle,
                        tool_call_id=tc.id,
                    )
                )
                normalized_result = raw_result or f"{tc.tool_name}: done"
                is_error, error_message = _error_from_tool_payload(raw_result)
                if (
                    tc.tool_name == TOOL_ACTIVATE
                    and not is_error
                    and _stack_signature(tracker_handle) != stack_before
                ):
                    ctx.record_activated_frames(_activated_frame_ids(tracker_handle))
                hooked = await apply_tool_result_hooks(
                    self._static_data.hooks,
                    tool_name=tc.tool_name,
                    arguments=dict(tc.tool_args),
                    value=normalized_result,
                    is_error=is_error,
                )
                persisted_result = serialize_tool_result_value(
                    tc.tool_name, hooked.value
                )
                span.update(output=persisted_result)
            persisted_is_error = hooked.is_error
            if persisted_is_error:
                _, hooked_error_message = _error_from_tool_payload(persisted_result)
                error_message = hooked_error_message or persisted_result
            else:
                error_message = None
            event_metadata = {
                METADATA_TOOL_CALL_ID: tc.id,
                METADATA_TOOL_BATCH_ID: tool_batch_id,
            }
            mcp_server = self._skill_executor.mcp_server_for_tool(
                tc.tool_name, tracker_handle
            )
            if mcp_server is not None:
                event_metadata["mcp_server"] = mcp_server
            active_skill_id, _ = tracker_handle.memory_scope()
            tracker_handle.apply_events(
                create_tool_execution_events(
                    tool_name=tc.tool_name,
                    arguments=dict(hooked.arguments),
                    source="mcp" if mcp_server is not None else "local",
                    result=persisted_result,
                    is_error=persisted_is_error,
                    error_message=error_message,
                    mcp_server=mcp_server,
                    metadata=event_metadata,
                    skill_id=active_skill_id or None,
                )
            )
            # Flush any memory validation tool events queued during dispatch so they
            # appear AFTER this tool's own ToolExecuted on the tracker.
            memory_validation_events = tracker_handle.drain_memory_validation_events()
            if memory_validation_events:
                tracker_handle.apply_events(memory_validation_events)
            queued = self._skill_executor.take_pending_tool_instructions()
            if queued and persisted_is_error:
                # A result hook turned this call into a failure; treat its
                # control flow as failed too.
                structlogger.warning(
                    "mantle.orchestrator.tool.next_dropped_by_hook",
                    tool_name=tc.tool_name,
                    count=len(queued),
                )
            else:
                next_instructions.extend(queued)

        if ctx.is_cancelled:
            raise OperationCancelled()
        self._skill_executor.run_tool_instructions(next_instructions, tracker_handle)

    async def _emit_turn_error_fallback(self, response_name: str) -> None:
        """Speak a packaged turn-error response after an abort.

        Used for fail-closed hook aborts and unknown main-model failures.
        Builders override the named templates in ``responses.yml``.
        ``metadata.rephrase`` is ignored because the model is not trusted on
        these paths. A missing or unmatched template
        speaks the packaged default, never the response name and never the
        exception text. If the turn is already cancelled, the utterance is
        skipped (same drop semantics as :meth:`MessageTurnContext.send`).
        """
        ctx = current_turn_context()
        if ctx.is_cancelled:
            structlogger.debug(
                "mantle.orchestrator.turn_error_fallback_skipped_cancelled",
                response_name=response_name,
            )
            return

        resolved = self._resolved_turn_error(response_name)
        await ctx.send(
            resolved.text,
            response_name=response_name,
            buttons=resolved.buttons,
            variant_metadata=resolved.variant_metadata,
        )

    def _resolved_turn_error(self, response_name: str) -> ResolvedUtterance:
        """Resolve a turn-error template, or the packaged sentence.

        A missing or unmatched template, and text that is only the response
        name, uses ``TURN_ERROR_DEFAULT_TEXT`` with no buttons and no rephrase.
        """
        resolved = self._skill_executor.resolve_response_name(
            response_name,
            current_turn_context().tracker_handle,
        )
        text = resolved.text.strip() if isinstance(resolved.text, str) else ""
        if not text or text == response_name:
            return ResolvedUtterance(text=TURN_ERROR_DEFAULT_TEXT)
        return resolved.model_copy(update={"text": text})

    async def _max_iterations_result(
        self,
        tracker_handle: TrackerHandle,
        turn: IncomingTurn,
        llm_client: LLMClient,
    ) -> TurnResult:
        """Stop the turn after the iteration cap and speak a recovery.

        Speaks ``utter_model_call_error`` as written. When the builder's
        variant sets ``metadata.rephrase``, it is rephrased once with no tools,
        and a failed or empty rephrase falls back to the text as written. The
        raw cap message stays on ``TurnResult.error`` and never reaches the
        user or the rephrase prompt.
        """
        ctx = current_turn_context()
        if ctx.is_cancelled:
            return self._cancelled_result(_MAX_ITERATIONS)

        structlogger.warning(
            "mantle.orchestrator.max_iterations",
            iteration_count=_MAX_ITERATIONS,
        )
        resolved = self._resolved_turn_error(UTTER_MODEL_CALL_ERROR)
        if isinstance(resolved.rephrase, NaturalRephrase):
            _, cancelled = await self._rephrase_and_send(
                resolved.text,
                tracker_handle,
                turn,
                llm_client,
                _MAX_ITERATIONS - 1,
                response_name=UTTER_MODEL_CALL_ERROR,
                buttons=resolved.buttons,
                variant_metadata=resolved.variant_metadata,
            )
            if cancelled is not None:
                return cancelled
        else:
            await ctx.send(
                resolved.text,
                response_name=UTTER_MODEL_CALL_ERROR,
                buttons=resolved.buttons,
                variant_metadata=resolved.variant_metadata,
            )
            if ctx.is_cancelled:
                return self._cancelled_result(_MAX_ITERATIONS)
        return self._completed(
            TurnResult(
                error=f"Max iterations ({_MAX_ITERATIONS}) exceeded",
                iteration_count=_MAX_ITERATIONS,
            ),
            source=_SOURCE_MAX_ITERATIONS,
        )

    async def _hook_error_result(
        self,
        exc: Exception,
        iteration: int,
        *,
        response_name: str,
    ) -> TurnResult:
        """Abort the turn after a fail-closed modify hook crash or timeout.

        Distinct from :meth:`_llm_error_result` so operators do not misread a
        guardrail failure as a provider outage. The user hears ``response_name``.
        """
        structlogger.error(
            "mantle.orchestrator.hook_error",
            error=str(exc),
            error_type=type(exc).__name__,
            iteration=iteration,
            response_name=response_name,
            exc_info=True,
        )
        await self._emit_turn_error_fallback(response_name)
        return self._completed(
            TurnResult(error=_HOOK_EXECUTION_FAILED, iteration_count=iteration),
            source=_SOURCE_HOOK_ERROR,
        )

    async def _llm_error_result(self, exc: Exception, iteration: int) -> TurnResult:
        """Abort the turn after an unexpected main-model call failure.

        The full exception (type + stack) is logged for operators, but
        ``TurnResult.error`` is a stable, provider-agnostic string so raw
        endpoint/model fragments cannot leak downstream. The user hears
        ``utter_model_call_error``.
        """
        structlogger.error(
            "mantle.orchestrator.llm_error",
            error=str(exc),
            error_type=type(exc).__name__,
            iteration=iteration,
            response_name=UTTER_MODEL_CALL_ERROR,
            exc_info=True,
        )
        await self._emit_turn_error_fallback(UTTER_MODEL_CALL_ERROR)
        return self._completed(
            TurnResult(error=_LLM_CALL_FAILED, iteration_count=iteration),
            source=_SOURCE_LLM_ERROR,
        )

    async def _skill_retrieval_error_result(
        self, exc: Exception, iteration: int
    ) -> TurnResult:
        """Turn a failed skill search into a completed, leak-free error result.

        The turn fails closed the same way as an LLM outage: no routing call,
        and the user hears ``utter_model_call_error``. The log event,
        completion source, and ``TurnResult.error`` stay distinct so operators
        do not chase the model provider. The log records the exception type
        only: the chained provider error can echo the query, so it is not
        attached.
        """
        structlogger.error(
            "mantle.orchestrator.skill_retrieval_error",
            error_type=type(exc).__name__,
            iteration=iteration,
            response_name=UTTER_MODEL_CALL_ERROR,
        )
        await self._emit_turn_error_fallback(UTTER_MODEL_CALL_ERROR)
        return self._completed(
            TurnResult(
                error="Skill retrieval search failed.",
                iteration_count=iteration,
            ),
            source=_SOURCE_SKILL_RETRIEVAL_ERROR,
        )

    def _cancelled_result(self, iteration: int) -> TurnResult:
        """Complete the turn early because it was cancelled (e.g. call teardown).

        Checked at several points in the loop — before the LLM call and before
        dispatching tool calls — and raised from in-flight LLM / tool / skill
        awaits via ``run_cancellable``, so an interrupt stops not just further
        agent responses but also work already underway.
        """
        structlogger.info(
            "mantle.orchestrator.turn_cancelled",
            iteration=iteration,
        )
        return self._completed(
            TurnResult(iteration_count=iteration, cancelled=True),
            source=_SOURCE_CANCELLED,
        )

    def _completed_or_cancelled(self, result: TurnResult, *, source: str) -> TurnResult:
        """Complete with *source*, unless the turn was cancelled while emitting.

        Cancellation can land after the LLM returns but before an emit-and-finish
        path returns. ``send`` drops the utterance, so the turn must also report
        the cancelled source rather than a normal success source.
        """
        if current_turn_context().is_cancelled:
            return self._cancelled_result(result.iteration_count)
        return self._completed(result, source=source)

    @staticmethod
    def _completed(result: TurnResult, *, source: str) -> TurnResult:
        """Log ``mantle.turn.completed`` and return the result."""
        structlogger.info(
            "mantle.turn.completed",
            iteration_count=result.iteration_count,
            source=source,
            error=result.error,
        )
        return result
